<script setup>
import { useCustomerPresentation } from '../../Composables/customerPresentation';
const { customerText } = useCustomerPresentation();
import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';import TurnstileWidget from '../../Components/TurnstileWidget.vue';
import GoogleMark from '../../Components/GoogleMark.vue';import CustomerShell from '../../Components/CustomerShell.vue';const page=usePage(),turnstile=ref(null),security=computed(()=>page.props.security||{}),form=useForm({email:'',password:'',remember:false,turnstile_token:''});const submit=()=>{if(form.processing)return;form.post('/login',{onFinish:()=>{form.reset('password');form.turnstile_token='';turnstile.value?.reset()}})};</script>
<template><Head :title="customerText('pages.auth.login.attribute.title.5f295534', 'Masuk')"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">{{ customerText("pages.auth.login.830e118b", "Selamat datang") }}</p><h1>{{ customerText("pages.auth.login.a68168e3", "Masuk LFAMILIA") }}</h1><p>{{ customerText("pages.auth.login.6a59b134", "Masuk untuk melihat saldo, pesanan, membership, tiket, dan profilmu.") }}</p><p v-if="page.props.errors?.google" role="alert" class="mb-3 text-xs text-red-300">{{page.props.errors.google}}</p><p v-if="page.props.status" role="status" class="mb-3 text-xs text-[#cfff72]">{{page.props.status}}</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.login.43352167", "Email") }}<input v-model="form.email" type="email" name="email" autocomplete="username" :placeholder="customerText('pages.auth.login.attribute.placeholder.e0b6cfa6', 'Masukkan email')" :aria-invalid="Boolean(form.errors.email)" required><span v-if="form.errors.email" role="alert" class="block mt-1 text-red-300">{{form.errors.email}}</span></label><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.login.2a776cdb", "Kata sandi") }}<input v-model="form.password" type="password" name="password" autocomplete="current-password" :placeholder="customerText('pages.auth.login.attribute.placeholder.18cb4bb4', 'Masukkan kata sandi')" :aria-invalid="Boolean(form.errors.password)" required><span v-if="form.errors.password" role="alert" class="block mt-1 text-red-300">{{form.errors.password}}</span></label><label class="flex items-center gap-2 text-xs"><input v-model="form.remember" type="checkbox" name="remember"> {{ customerText("pages.auth.login.dfa9069c", "Ingat saya") }}</label><TurnstileWidget v-if="security.turnstile_required" ref="turnstile" :site-key="security.turnstile_site_key" :action="security.turnstile_action" @token="form.turnstile_token=$event"/><p v-if="form.errors.turnstile_token" role="alert" class="text-xs text-red-300">{{form.errors.turnstile_token}}</p><button type="submit" class="lf-primary w-full" :disabled="form.processing">{{form.processing?'Memproses…':'Masuk'}}</button><a href="/auth/google/redirect" class="lf-secondary w-full gap-3" aria-label="Masuk dengan Google"><GoogleMark />{{ customerText("pages.auth.login.81e6381a", "Masuk dengan Google") }}</a></div><div class="lf-auth-links"><Link href="/forgot-password">{{ customerText("pages.auth.login.1c997073", "Lupa password?") }}</Link><Link href="/register">{{ customerText("pages.auth.login.5e0b087f", "Daftar") }}</Link></div></form></main></CustomerShell></template>